WITH cleaned AS (SELECT *, ROUND(quantity, 0) quantity_rounded FROM order_items WHERE order_id IN (13, 26, 27, 28)), cleaned_order_items AS (SELECT *, CASE WHEN quantity >= 8 THEN 'High' WHEN quantity >= 4 THEN 'Medium' ELSE 'Low' END quantity_band, ROUND(quantity, 0) quantity_rounded_2 FROM cleaned WHERE order_id = 8), scored AS (SELECT id, order_id, unit_price, quantity_rounded, quantity_band, LEAD(quantity_rounded_2) OVER w_running next_quantity_rounded_2, LAG(quantity_rounded_2) OVER w_running prev_quantity_rounded_2, LEAD(quantity_rounded) OVER w_running next_quantity_rounded, ROW_NUMBER() OVER w_running seq_no FROM cleaned_order_items WINDOW w_running AS (PARTITION BY product_id, order_id ORDER BY quantity, id)), joined AS (SELECT a.id, a.order_id, a.unit_price, a.quantity_band, a.prev_quantity_rounded_2, a.next_quantity_rounded, o.shipping_fee, o.channel FROM scored a LEFT JOIN orders o ON a.order_id = o.id), metrics AS (SELECT *, COUNT(unit_price) OVER (PARTITION BY channel) channel_count_unit_price, NTILE(5) OVER w_running prev_quantity_rounded_2_bucket, NTILE(10) OVER (PARTITION BY order_id ORDER BY unit_price, id) unit_price_bucket FROM joined WHERE channel <> 'store' WINDOW w_running AS (PARTITION BY order_id, channel ORDER BY prev_quantity_rounded_2, id)) SELECT s.id, s.order_id, s.quantity_band, s.prev_quantity_rounded_2, s.shipping_fee, s.channel_count_unit_price, (SELECT SUM(o2.quantity) FROM order_items o2 WHERE o2.order_id = s.order_id) AS sum_order_item_quantity FROM metrics s ORDER BY prev_quantity_rounded_2 DESC NULLS FIRST
